<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {api,fmt} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import EChart from '@/components/EChart.vue';import {ArrowDownToLine,Box,ChartNoAxesCombined,CircleDollarSign,Megaphone,Wallet} from 'lucide-vue-next';
const data=ref<any>({metrics:{},trend:[],topProducts:[],siteProfit:[]}),sites=ref<any[]>([]),filter=ref({start:'',end:'',siteId:''});async function load(){data.value=await api('/dashboard?'+new URLSearchParams(filter.value).toString())}onMounted(async()=>{sites.value=await api('/sites');await load()});
const cards=computed(()=>[['总投入',data.value.metrics.totalInvestment,CircleDollarSign,'text-indigo-600','bg-indigo-50'],['库存价值',data.value.metrics.inventoryValue,Box,'text-sky-600','bg-sky-50'],['广告投入',data.value.metrics.adSpend,Megaphone,'text-orange-600','bg-orange-50'],['销售毛利',data.value.metrics.salesProfit,ChartNoAxesCombined,'text-emerald-600','bg-emerald-50'],['提现金额',data.value.metrics.withdrawals,ArrowDownToLine,'text-violet-600','bg-violet-50'],['净盈亏',data.value.metrics.netProfit,Wallet,data.value.metrics.netProfit>=0?'text-emerald-600':'text-red-600',data.value.metrics.netProfit>=0?'bg-emerald-50':'bg-red-50']]);
const trendOption=computed(()=>({tooltip:{trigger:'axis'},legend:{data:['到账金额','销售毛利','广告投入'],bottom:0},grid:{left:45,right:20,top:25,bottom:45},xAxis:{type:'category',data:data.value.trend.map((x:any)=>x.date),axisLine:{lineStyle:{color:'#dfe7e4'}}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf2f0'}}},series:[['到账金额','revenue','#18a77b'],['销售毛利','profit','#6366f1'],['广告投入','ads','#f59e0b']].map(([name,key,color])=>({name,type:'line',smooth:true,symbolSize:7,itemStyle:{color},areaStyle:{color:color+'16'},data:data.value.trend.map((x:any)=>x[key as string])}))}));
const siteOption=computed(()=>({tooltip:{trigger:'axis'},grid:{left:45,right:20,top:20,bottom:35},xAxis:{type:'category',data:data.value.siteProfit.map((x:any)=>x.name)},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf2f0'}}},series:[{type:'bar',data:data.value.siteProfit.map((x:any)=>x.profit),itemStyle:{color:'#18a77b',borderRadius:[6,6,0,0]},barMaxWidth:42}]}));
</script>
<template><PageHeader title="经营看板" subtitle="掌握销售、投入、库存与现金流的核心变化"><div class="flex flex-wrap gap-2"><el-date-picker v-model="filter.start" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="filter.end" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-select v-model="filter.siteId" clearable placeholder="全部站点" class="!w-44"><el-option v-for="s in sites" :key="s.id" :label="s.name" :value="String(s.id)"/></el-select><el-button type="primary" @click="load">应用筛选</el-button></div></PageHeader><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><el-card v-for="[label,value,Icon,color,bg] in cards" shadow="never"><div class="flex items-center gap-4"><div :class="['rounded-2xl p-3',bg]"><component :is="Icon" :class="color"/></div><el-statistic :title="label" :value="Number(value||0)" :precision="2" prefix="¥ "/></div></el-card></div><div class="mt-5 grid gap-5 xl:grid-cols-3"><el-card shadow="never" class="xl:col-span-2"><h3 class="font-semibold">经营趋势</h3><EChart :option="trendOption"/></el-card><el-card shadow="never"><h3 class="font-semibold">站点毛利</h3><EChart :option="siteOption"/></el-card></div><el-card shadow="never" class="mt-5"><h3 class="mb-4 font-semibold">热销商品</h3><el-table :data="data.topProducts" stripe empty-text="暂无销售数据"><el-table-column prop="sku" label="SKU"/><el-table-column prop="name" label="商品"/><el-table-column prop="quantity" label="销量"/><el-table-column label="毛利"><template #default="{row}"><el-text :type="row.profit>=0?'success':'danger'">¥ {{fmt(row.profit)}}</el-text></template></el-table-column></el-table></el-card></template>
